window.CDL_QUESTIONS = [
  { id: "gk-01", category: "general", topic: "License class", q: "What combination generally requires a California Class A CDL?", choices: ["Any vehicle towing a trailer", "A combination with a GCWR of 26,001 pounds or more when the towed vehicle(s) have a GVWR over 10,000 pounds", "Any truck over 10,000 pounds GVWR", "Any passenger vehicle with more than 8 seats"], a: 1, why: "Class A covers heavy combinations: GCWR of 26,001+ when the towed unit(s) exceed 10,000 pounds GVWR." },
  { id: "gk-02", category: "general", topic: "Age", q: "What is the minimum age to operate a CMV in interstate commerce?", choices: ["18", "19", "20", "21"], a: 3, why: "Interstate commercial driving requires age 21. Intrastate-for-hire driving in California may begin at 18 if other requirements are met." },
  { id: "gk-03", category: "general", topic: "Age", q: "At what age may you drive a commercial vehicle for hire only within California, if you meet the other requirements?", choices: ["16", "18", "20", "21"], a: 1, why: "California allows intrastate-for-hire CMV operation at 18. Interstate operation requires 21." },
  { id: "gk-04", category: "general", topic: "Inspection", q: "When should a pre-trip inspection be completed?", choices: ["At least once a week", "Only if problems occurred last trip", "Before operating the vehicle", "Only after an accident"], a: 2, why: "The handbook requires a vehicle inspection before operating so defects are found before you drive." },
  { id: "gk-05", category: "general", topic: "En-route inspection", q: "Whenever you stop during a trip, you should check:", choices: ["Only the fuel gauge", "Tires, wheels, brakes, lights, and cargo securement", "Only cargo papers", "Only the mirrors"], a: 1, why: "En-route checks include tires, wheels/rims, brakes, lighting, coupling devices, and cargo tie-downs." },
  { id: "gk-06", category: "general", topic: "Seeing", q: "How far ahead should a commercial driver generally look?", choices: ["2–3 seconds", "5–6 seconds", "12–15 seconds", "About one city block only at night"], a: 2, why: "Looking 12 to 15 seconds ahead gives time to spot hazards and plan a smooth response." },
  { id: "gk-07", category: "general", topic: "Following distance", q: "Below 40 mph, a safe following-distance rule is:", choices: ["One second for every 10 feet of vehicle length", "Two seconds total", "One second for every axle", "Five seconds total regardless of length"], a: 0, why: "Allow at least 1 second for each 10 feet of vehicle length at speeds under 40 mph." },
  { id: "gk-08", category: "general", topic: "Following distance", q: "When traveling over 40 mph, what should you add to the basic following-distance rule?", choices: ["Nothing", "One extra second", "Five extra seconds", "One extra second per axle"], a: 1, why: "Above 40 mph, add 1 extra second to the 1-second-per-10-feet rule." },
  { id: "gk-09", category: "general", topic: "Curves", q: "What is the safest way to take a curve in a commercial vehicle?", choices: ["Brake hard in the curve", "Shift gears in the middle of the curve", "Slow to a safe speed before entering, then accelerate slightly through it", "Use the posted car speed regardless of load"], a: 2, why: "Slow before the curve. Braking in a curve can lock wheels and cause a skid or rollover." },
  { id: "gk-10", category: "general", topic: "Curves", q: "Why is braking in a curve dangerous?", choices: ["It makes the engine overheat", "Wheels can lock and the vehicle can skid or roll", "It charges the air tanks too fast", "It always improves traction"], a: 1, why: "Braking in a curve can lock wheels, reduce steering control, and cause a skid or rollover." },
  { id: "gk-11", category: "general", topic: "Clearance", q: "If you are not sure your vehicle will clear an overhead object, you should:", choices: ["Speed up to get through quickly", "Follow the truck ahead closely", "Slow down and use another route if clearance remains uncertain", "Drive on the shoulder"], a: 2, why: "Never guess on overhead clearance. Slow, stop if needed, and choose a known-clear route." },
  { id: "gk-12", category: "general", topic: "Clearance", q: "Which statement about overhead clearance is true?", choices: ["Posted heights are always exact", "Packed snow, ice, or a recently paved surface can reduce clearance", "An empty trailer always has more clearance than a loaded one", "You can ignore posted heights at night"], a: 1, why: "Posted clearance can be wrong after paving, snow pack, or other changes. Know your actual height." },
  { id: "gk-13", category: "general", topic: "Backing", q: "The safest backing practice is to:", choices: ["Back quickly to reduce exposure", "Avoid backing whenever possible, and get out and look first", "Use only the right mirror", "Never make a pull-up"], a: 1, why: "Backing is a high-crash maneuver. Avoid it when you can; walk the path and use a helper when needed." },
  { id: "gk-14", category: "general", topic: "Backing", q: "When backing a trailer, you initially turn the steering wheel:", choices: ["In the same direction you want the trailer to go", "In the opposite direction from the desired trailer path", "Only after the trailer is moving fast", "Straight, then wait for the trailer to hunt"], a: 1, why: "To start a trailer turning, steer opposite the desired trailer direction, then follow the trailer." },
  { id: "gk-15", category: "general", topic: "Stopping", q: "How should you normally make a safe stop?", choices: ["Slam the pedal", "Apply brake pressure gradually and smoothly", "Shift to neutral immediately", "Pull the parking brake while moving"], a: 1, why: "Smooth, controlled braking keeps the vehicle stable and reduces skid risk." },
  { id: "gk-16", category: "general", topic: "Night driving", q: "When driving at night you should:", choices: ["Drive slowly enough to stop within the range of your headlights", "Roll the window down instead of resting if sleepy", "Rely on caffeine if you are drowsy", "Use high beams in fog"], a: 0, why: "Night seeing distance is limited. You must be able to stop within headlight range." },
  { id: "gk-17", category: "general", topic: "Fatigue", q: "If you feel drowsy while driving, the safe action is to:", choices: ["Open the window and keep going", "Drink coffee and drive faster to finish sooner", "Stop in a safe place and rest", "Turn the radio up"], a: 2, why: "Sleep is the only real cure. Stop in a safe place and rest before continuing." },
  { id: "gk-18", category: "general", topic: "Railroad", q: "Before crossing railroad tracks you should:", choices: ["Shift while on the tracks to save time", "Make sure you have enough space to clear the tracks on the far side", "Stop on the tracks if traffic ahead is moving", "Follow the vehicle ahead closely"], a: 1, why: "Never start across unless the entire vehicle will clear the tracks. Do not shift while crossing." },
  { id: "gk-19", category: "general", topic: "Railroad", q: "Why should you avoid shifting gears while crossing railroad tracks?", choices: ["It may stall the vehicle on the tracks", "It saves fuel", "It improves traction", "It is required by ABS"], a: 0, why: "A stall on the tracks is extremely dangerous. Cross in a gear that will get you all the way over." },
  { id: "gk-20", category: "general", topic: "Fires", q: "If your vehicle catches fire, the first actions are to:", choices: ["Keep driving to a shop", "Pull over safely, park, and get everyone out", "Open the hood immediately on an engine fire", "Pour water on burning fuel"], a: 1, why: "Get the vehicle off the roadway if you can, park, shut off, and get people out before fighting the fire." },
  { id: "gk-21", category: "general", topic: "Fires", q: "Water can safely be used on which of these fires?", choices: ["Electrical fires", "Gasoline or oil fires", "Ordinary combustibles such as wood, paper, or cloth", "All of the above"], a: 2, why: "Water works on Class A ordinary combustibles. Do not use water on electrical or fuel fires." },
  { id: "gk-22", category: "general", topic: "Warning devices", q: "If you break down, reflective warning devices should be placed:", choices: ["Only behind the truck, 10 feet away", "According to traffic direction, road type, and sight distance", "Inside the cab", "Directly under the trailer"], a: 1, why: "Placement depends on two-lane, divided, hills, and curves so approaching drivers see the warning in time." },
  { id: "gk-23", category: "general", topic: "Warning devices", q: "If stopped on a one-way or divided highway, place reflective triangles:", choices: ["10, 100, and 200 feet toward approaching traffic", "Only 10 feet behind the vehicle", "In front of the vehicle only", "At 500 feet on both sides"], a: 0, why: "On a divided or one-way road, place triangles 10, 100, and 200 feet toward approaching traffic." },
  { id: "gk-24", category: "general", topic: "Emergency equipment", q: "Which three kinds of emergency equipment must you have?", choices: ["Fire extinguisher, spare electrical fuses (unless equipped with circuit breakers), and warning devices", "Jumper cables, extra fuel, and a radio", "Only a fire extinguisher", "Spare tire, jack, and lug wrench only"], a: 0, why: "Federal/state rules require a fire extinguisher, spare fuses if needed, and warning devices such as 3 red triangles." },
  { id: "gk-25", category: "general", topic: "Tires", q: "What is the minimum tread depth for front (steering) tires?", choices: ["2/32 inch", "4/32 inch", "6/32 inch", "1/8 inch in only one groove"], a: 1, why: "Steering-axle tires need at least 4/32 inch tread in every major groove. Other tires need 2/32 inch." },
  { id: "gk-26", category: "general", topic: "Tires", q: "What is the minimum tread depth for tires other than the front steering tires?", choices: ["1/32 inch", "2/32 inch", "4/32 inch", "8/32 inch"], a: 1, why: "Non-steering tires must have at least 2/32 inch tread depth in every major groove." },
  { id: "gk-27", category: "general", topic: "Steering", q: "Steering play is generally too much if a 20-inch steering wheel moves more than:", choices: ["1/2 inch before the tires move", "2 inches (about 10 degrees) before the front tires move", "6 inches", "A full turn"], a: 1, why: "More than about 10 degrees of play (2 inches on a 20-inch wheel) is a defect that must be fixed before driving." },
  { id: "gk-28", category: "general", topic: "Cooling system", q: "If a coolant container is part of a pressurized system, you should:", choices: ["Remove the radiator cap while the engine is hot", "Never remove the cap until the system has cooled", "Use water only, never coolant", "Check coolant only while driving"], a: 1, why: "Removing a hot pressurized cap can cause severe burns. Wait until the system cools." },
  { id: "gk-29", category: "general", topic: "Cargo", q: "Before starting a trip, cargo should be:", choices: ["Loaded loosely for ventilation", "Properly secured against shifting, falling, or damaging the vehicle", "Placed only at the rear", "Covered only if rain is expected"], a: 1, why: "Cargo must be balanced and secured so it cannot shift, fall, or make the vehicle unstable." },
  { id: "gk-30", category: "general", topic: "Cargo", q: "Where should the heaviest cargo normally be placed?", choices: ["High and toward the rear", "Low and as close to the center as practical", "On one side only", "On the roof"], a: 1, why: "Low, centered cargo keeps the center of gravity down and helps steering, traction, and rollover resistance." },
  { id: "gk-31", category: "general", topic: "Cargo", q: "Why should cargo not be stacked too high?", choices: ["It raises the center of gravity and increases rollover risk", "It always reduces legal weight", "It makes the truck quieter", "It prevents use of mirrors"], a: 0, why: "A high center of gravity is a major rollover factor, especially in curves and on ramps." },
  { id: "gk-32", category: "general", topic: "Cargo", q: "Containerized loads:", choices: ["Are exempt from weight limits", "Are generally used when freight is carried part way by rail or ship", "Never need securement", "Must always be opened before driving"], a: 1, why: "Containers are common in intermodal moves (ship/rail/truck). They still must be secured and legal in weight." },
  { id: "gk-33", category: "general", topic: "Cargo", q: "After starting a trip, when should you recheck cargo securement?", choices: ["Only at the destination", "Within the first 50 miles and whenever you make a duty-status change or have been driving 3 hours or 150 miles", "Only in rain", "Never if the trailer is sealed"], a: 1, why: "Federal cargo-securement rules require an early recheck and periodic checks, including sealed loads' visible securement." },
  { id: "gk-34", category: "general", topic: "Weight", q: "The term Gross Combination Weight (GCW) refers to:", choices: ["The tractor weight only", "The total weight of the powered unit, trailer(s), and cargo", "Cargo weight only", "Axle weight only"], a: 1, why: "GCW is the actual total weight of the combination. GCWR is the rating." },
  { id: "gk-35", category: "general", topic: "Weight", q: "A bridge formula is used to:", choices: ["Set posted bridge heights", "Limit axle weights based on axle spacing to protect bridges and roadways", "Calculate fuel tax", "Set speed limits"], a: 1, why: "Closer axles are allowed less weight so bridges are not overloaded." },
  { id: "gk-36", category: "general", topic: "Mountains", q: "Before starting down a long, steep grade you should:", choices: ["Wait until speed builds, then downshift", "Select a safe low gear before starting down", "Use only the brakes and stay in high gear", "Shift to neutral to save fuel"], a: 1, why: "Choose the proper low gear before the downgrade so engine braking controls speed and brakes do not overheat." },
  { id: "gk-37", category: "general", topic: "Mountains", q: "You are about to go down a long, steep grade in a newer truck. You should:", choices: ["Use a lower gear than you would use to climb the same grade", "Use a higher gear than the climb", "Coast in neutral", "Ride the brake lightly the whole way in high gear"], a: 0, why: "Newer trucks often need an even lower gear going down than they used going up because they are more aerodynamic and roll easier." },
  { id: "gk-38", category: "general", topic: "Brake fade", q: "Why should you rely on engine braking on long or steep downgrades?", choices: ["To avoid excessive brake heat that can cause fade or failure", "To increase tire pressure", "To make shifting easier", "To reduce the need to steer"], a: 0, why: "Service brakes can overheat, fade, and fail. Use a low gear so engine braking does most of the work." },
  { id: "gk-39", category: "general", topic: "Brake fade", q: "If you need more and more brake pressure to hold the same speed downhill, the brakes are:", choices: ["Working better", "Fading from heat", "Automatically adjusting", "Charging the air tanks"], a: 1, why: "Rising application pressure for the same speed is a classic sign of brake fade. Slow down and use a lower gear." },
  { id: "gk-40", category: "general", topic: "Escape ramp", q: "If brakes fail on a downgrade and an escape ramp is available, you should:", choices: ["Continue and pump the brakes", "Use the escape ramp", "Shut off the engine immediately while moving", "Shift to high gear"], a: 1, why: "Escape ramps are built to stop runaway vehicles. Use one if brakes fail on a grade." },
  { id: "gk-41", category: "general", topic: "Off-ramp", q: "You are exiting on a downhill curved offramp in a heavy vehicle. You should:", choices: ["Take the ramp at highway speed", "Slow to a safe speed before the curve", "Brake hard in the middle of the curve", "Downshift in the sharpest part of the curve"], a: 1, why: "Ramps are often sharper and downhill. Slow before the curve so the vehicle does not roll or run wide." },
  { id: "gk-42", category: "general", topic: "Skids", q: "What is generally the best first response to a tire blowout?", choices: ["Brake hard immediately", "Hold the wheel firmly, stay off the brake at first, ease off the throttle, and stop safely", "Turn sharply onto the shoulder", "Shift into reverse"], a: 1, why: "A sudden hard brake can cause a skid. Keep control, slow gradually, then inspect." },
  { id: "gk-43", category: "general", topic: "Skids", q: "If wheels lock on a slippery road in a vehicle without ABS, you may:", choices: ["Gain more steering control", "Lose steering control and skid, jackknife, or spin", "Stop perfectly straight every time", "Disconnect the trailer safely"], a: 1, why: "Locked wheels do not steer. That can cause a skid, jackknife, or spin." },
  { id: "gk-44", category: "general", topic: "Emergency braking", q: "Which methods are identified for a quick, controlled stop without ABS?", choices: ["Controlled braking or stab braking", "Parking-brake only", "Neutral-coast braking", "Clutch-only braking"], a: 0, why: "Controlled braking (hard without lockup) and stab braking (full apply, release when locked, reapply) are the handbook methods." },
  { id: "gk-45", category: "general", topic: "Seat belt", q: "When should you use a seat belt in a commercial vehicle?", choices: ["Only in rain", "Only on highways", "Whenever you are on the road", "Only when hauling cargo"], a: 2, why: "Wear the seat belt whenever the vehicle is on the road. It keeps you in control in a crash or sudden stop." },
  { id: "gk-46", category: "general", topic: "Parking", q: "When leaving your commercial vehicle you should:", choices: ["Leave it in gear only", "Apply the parking brake", "Leave the engine running unattended", "Turn on high beams"], a: 1, why: "Always set the parking brake. Also secure the vehicle as required (keys, chocks if needed)." },
  { id: "gk-47", category: "general", topic: "Parking", q: "You should plan parking so that:", choices: ["You will need to back out through traffic", "You can pull forward out of the space when possible", "The trailer blocks a fire hydrant", "The vehicle hides warning triangles"], a: 1, why: "Plan to leave without backing when you can. Backing out of a space is a common crash setup." },
  { id: "gk-48", category: "general", topic: "Senses", q: "What four senses help you detect vehicle trouble during a trip?", choices: ["Look, listen, smell, and feel", "Taste, touch, hear, and guess", "Read, write, count, and signal", "Watch, walk, wave, and wait"], a: 0, why: "Use sight, hearing, smell, and feel (vibration, pull, softness) to catch problems early." },
  { id: "gk-49", category: "general", topic: "Hazards", q: "The most important reason to do a vehicle inspection is to:", choices: ["Save fuel", "Find problems that could cause a crash or breakdown", "Avoid wearing a seat belt", "Skip the skills test"], a: 1, why: "Safety is the purpose: catch defects before they cause a crash, fire, or breakdown." },
  { id: "gk-50", category: "general", topic: "Exhaust", q: "A leaking exhaust system is dangerous because:", choices: ["It always improves fuel economy", "Poisonous fumes such as carbon monoxide can enter the cab", "It charges the air tanks", "It cools the brakes"], a: 1, why: "Exhaust leaks can put carbon monoxide into the cab, especially with windows closed." },
  { id: "gk-51", category: "general", topic: "Turns", q: "On a left turn in a long vehicle, you should:", choices: ["Start turning as soon as the bumper enters the intersection", "Reach the center of the intersection before starting the turn so off-tracking does not hit vehicles on the left", "Turn from the right shoulder", "Swing right into the adjacent lane of oncoming traffic as a habit"], a: 1, why: "If you turn too soon, the left side off-tracks into other vehicles. Get far enough into the intersection first." },
  { id: "gk-52", category: "general", topic: "Space", q: "You need extra space in front when:", choices: ["The road is dry and empty", "You are being tailgated, driving in rain or ice, or following another truck", "You are empty", "You have ABS"], a: 1, why: "Poor traction, limited sight, and tailgaters all require more space so you can stop smoothly." },
  { id: "gk-53", category: "general", topic: "Tailgaters", q: "If you are being tailgated, you should:", choices: ["Brake-check the other driver", "Speed up well above the limit", "Avoid quick changes and open up more space ahead so you can slow gradually", "Move left and stop"], a: 2, why: "Do not aggravate a tailgater. Increase following distance so your own stops are gradual." },
  { id: "gk-54", category: "general", topic: "Hydroplane", q: "Hydroplaning is more likely when:", choices: ["Tires have little tread and water is standing on the road", "Tires are new and the road is dry", "You drive very slowly in a dual-tire axle", "The pavement is grooved and dry"], a: 0, why: "Light vehicles, worn tread, and standing water raise hydroplaning risk. Partial hydroplaning can start at relatively low speeds." },
  { id: "gk-55", category: "general", topic: "Winter", q: "In winter, you should pay extra attention to:", choices: ["Coolant/antifreeze, defrosters, wipers, exhaust leaks, and tire chains if required", "Only the radio", "Only cargo papers", "Only the horn"], a: 0, why: "Winter checks focus on seeing, cooling-system freeze protection, exhaust leaks into a closed cab, and traction equipment." },
  { id: "gk-56", category: "general", topic: "Fog", q: "When heavy fog occurs you should:", choices: ["Use high beams and maintain highway speed", "Slow to a speed that matches visibility, or stop off the roadway in a safe place if you cannot see well enough to drive", "Follow the taillights ahead as closely as possible", "Drive on the shoulder at normal speed"], a: 1, why: "If you cannot see far enough to drive safely, get off the road in a safe, legal place and wait." },
  { id: "gk-57", category: "general", topic: "Alcohol", q: "You will be placed out of service for 24 hours if you operate a CMV with:", choices: ["Any detectable amount of alcohol under 0.04", "A coffee drink", "A cold medicine that does not cause drowsiness", "Zero alcohol and a valid CDL"], a: 0, why: "Any detectable alcohol below 0.04 still means a 24-hour out-of-service order. 0.04 or more is a CDL alcohol violation." },
  { id: "gk-58", category: "general", topic: "Hours", q: "After coming on duty following 10 hours off, interstate property-carrying drivers generally may not drive beyond the:", choices: ["8th hour", "11th driving hour / 14th hour on duty window", "24th hour", "30th hour"], a: 1, why: "Federal interstate rules: 11 hours driving within a 14-hour window after 10 consecutive hours off (subject to current FMCSA details)." },
  { id: "gk-59", category: "general", topic: "Key", q: "During the vehicle inspection test, why put the starter-switch key in your pocket?", choices: ["So nobody can move the vehicle while you are under or around it", "To drain the air tanks", "To disable ABS", "It is only a habit for Class C"], a: 0, why: "Keep the key so the vehicle cannot be started while you are inspecting around or under it." },
  { id: "gk-60", category: "general", topic: "Hydraulic brakes", q: "How do you test hydraulic brakes for leaks?", choices: ["Pump 3 times, then hold firm pressure for 5 seconds; the pedal should not move", "Drain the master cylinder", "Drive at highway speed and slam the pedal", "Listen to the horn"], a: 0, why: "Pedal movement while holding pressure indicates a leak or other hydraulic problem." },

  { id: "ab-01", category: "airBrakes", topic: "Compressor", q: "Why does an air-brake system need an air compressor?", choices: ["To cool the engine", "To build and maintain air pressure for the brakes", "To power the headlights", "To steer the truck"], a: 1, why: "The compressor pumps air into the storage tanks so the brakes have pressure to operate." },
  { id: "ab-02", category: "airBrakes", topic: "Governor", q: "What does the air compressor governor control?", choices: ["Tire pressure", "Engine oil pressure", "When the compressor cuts in and cuts out", "Trailer ride height"], a: 2, why: "The governor stops pumping at cut-out (around 125 psi) and starts again at cut-in (around 100 psi)." },
  { id: "ab-03", category: "airBrakes", topic: "Governor", q: "Governor cut-out pressure is typically around:", choices: ["55 psi", "85 psi", "125 psi (often in a 120–140 psi range)", "200 psi"], a: 2, why: "Handbook: cut-out is around 125 psi, commonly 120–140 psi depending on the vehicle." },
  { id: "ab-04", category: "airBrakes", topic: "Governor", q: "Governor cut-in pressure is typically around:", choices: ["20 psi", "55 psi", "100 psi", "150 psi"], a: 2, why: "When tank pressure falls to about 100 psi, the governor lets the compressor pump again." },
  { id: "ab-05", category: "airBrakes", topic: "Tanks", q: "A primary purpose of air tanks is to:", choices: ["Store pressurized air", "Store fuel", "Store coolant", "Store engine oil"], a: 0, why: "Reservoirs store compressed air so you have a supply for braking." },
  { id: "ab-06", category: "airBrakes", topic: "Drain", q: "Why must air tanks be drained?", choices: ["To remove water and oil that can freeze or damage the system", "To add air pressure", "To cool the drums", "To increase governor cut-out"], a: 0, why: "Compressed air contains water and oil. Water can freeze valves in cold weather; oil and water damage the system." },
  { id: "ab-07", category: "airBrakes", topic: "Safety valve", q: "The safety relief valve on the first air tank is usually set to open at about:", choices: ["100 psi", "125 psi", "150 psi", "200 psi"], a: 2, why: "The safety valve protects the tank from too much pressure and typically opens at 150 psi. If it blows, something is wrong." },
  { id: "ab-08", category: "airBrakes", topic: "Low air", q: "A visible low-air-pressure warning must come on when pressure falls to:", choices: ["Between 55 and 75 psi (before 55 psi)", "Exactly 20 psi", "150 psi", "Only after spring brakes apply"], a: 0, why: "The warning must activate between 55 and 75 psi, and before pressure drops below 55 psi." },
  { id: "ab-09", category: "airBrakes", topic: "Low air", q: "When the low-air warning first comes on, you should:", choices: ["Keep driving to the next truck stop", "Bring the vehicle to a safe stop while you still have braking control", "Pump the pedal rapidly to restore pressure", "Wait for spring brakes to apply automatically"], a: 1, why: "Do not wait for automatic spring-brake application. Stop safely while you can still control the brakes." },
  { id: "ab-10", category: "airBrakes", topic: "Spring brakes", q: "Spring brakes are used for:", choices: ["Service braking only", "Parking and emergency braking", "Cooling drums", "Steering"], a: 1, why: "Powerful springs apply the parking/emergency brakes when air is released. Air pressure holds the springs back while driving." },
  { id: "ab-11", category: "airBrakes", topic: "Spring brakes", q: "Tractor and straight-truck spring brakes typically come fully on when air pressure drops to about:", choices: ["100 psi", "75 psi", "20 to 45 psi (often 20 to 30 psi)", "150 psi"], a: 2, why: "When pressure falls into the 20–45 psi range, spring brakes apply. Stop before that happens." },
  { id: "ab-12", category: "airBrakes", topic: "Spring brakes", q: "Why should you never push the brake pedal while the spring brakes are on?", choices: ["You can damage the brakes by combining spring force and air-apply force", "It increases fuel use", "It turns off ABS permanently", "It drains the fuel tank"], a: 0, why: "Combined spring and air forces can damage brake components. Do not press the pedal with parking springs applied." },
  { id: "ab-13", category: "airBrakes", topic: "Parking control", q: "On newer vehicles, the parking-brake control is:", choices: ["A red octagon knob", "A diamond-shaped yellow push-pull knob: pull out to apply, push in to release", "A blue round switch on the floor", "The trailer hand valve only"], a: 1, why: "Yellow diamond knob = parking brakes. Pull out applies; push in releases." },
  { id: "ab-14", category: "airBrakes", topic: "Brake lag", q: "Brake lag is:", choices: ["The delay between pushing the pedal and the brakes taking hold, due to air moving through the system", "Engine start delay", "Shift delay", "Trailer coupling delay"], a: 0, why: "Air takes time to flow to the chambers. That added distance is brake lag, unique to air brakes compared with hydraulic." },
  { id: "ab-15", category: "airBrakes", topic: "Stopping distance", q: "Total stopping distance with air brakes includes:", choices: ["Perception distance only", "Perception, reaction, brake-lag, and braking distance", "Braking distance only", "Following distance only"], a: 1, why: "Air-brake stopping distance adds perception + reaction + brake lag + braking distance." },
  { id: "ab-16", category: "airBrakes", topic: "ABS", q: "ABS helps prevent:", choices: ["Engine overspeed", "Wheel lockup during hard braking so you can keep steering control", "All air leaks", "The need for following distance"], a: 1, why: "ABS reduces lockup. It does not guarantee shorter stops and does not let you drive faster." },
  { id: "ab-17", category: "airBrakes", topic: "ABS", q: "Does ABS allow you to drive faster or follow more closely on slippery roads?", choices: ["Yes, always", "Yes, if loaded", "No", "Only with a trailer"], a: 2, why: "Handbook: ABS will not allow you to drive faster, follow more closely, or drive less carefully." },
  { id: "ab-18", category: "airBrakes", topic: "ABS", q: "If ABS activates, you should generally:", choices: ["Pump the brakes", "Keep firm, steady pressure on the pedal", "Release all braking and coast", "Apply the parking brake"], a: 1, why: "Do not pump ABS. Maintain firm pressure and steer. ABS pulses faster than you can pump." },
  { id: "ab-19", category: "airBrakes", topic: "ABS lamps", q: "A yellow ABS lamp that stays on after the bulb check means:", choices: ["ABS is working perfectly", "You may have lost ABS control on one or more wheels; you still have regular brakes", "The air compressor has failed", "Spring brakes are applied"], a: 1, why: "A lamp that stays on or comes on while driving indicates an ABS fault. Normal brakes still work; get ABS serviced." },
  { id: "ab-20", category: "airBrakes", topic: "Dual system", q: "A dual air-brake system is:", choices: ["Two separate air-brake systems that share one set of controls", "Two steering wheels", "A trailer-only system", "A system without spring brakes"], a: 0, why: "Primary and secondary systems have their own tanks and lines but one brake pedal. If one fails, the other can still brake." },
  { id: "ab-21", category: "airBrakes", topic: "Dual system", q: "Before driving a dual air system, build at least how much pressure in both primary and secondary systems?", choices: ["55 psi", "75 psi", "100 psi", "150 psi"], a: 2, why: "Allow the compressor to build a minimum of 100 psi in both systems before driving." },
  { id: "ab-22", category: "airBrakes", topic: "Check valve", q: "A one-way check valve between the compressor and the first tank:", choices: ["Lets air flow only toward the tank so a compressor leak will not empty the tanks", "Drains water automatically", "Applies spring brakes", "Cuts in the governor"], a: 0, why: "The check valve keeps stored air from leaking back out through a failed compressor." },
  { id: "ab-23", category: "airBrakes", topic: "Slack adjusters", q: "If you pull a slack adjuster and it moves more than about one inch where the push rod attaches, the brake:", choices: ["Is perfect", "Probably needs adjustment or has a mechanical problem", "Has too little slack", "Is an ABS fault"], a: 1, why: "More than about 1 inch of movement means the brake is out of adjustment or the automatic adjuster/foundation brake has a problem." },
  { id: "ab-24", category: "airBrakes", topic: "Linings", q: "Brake linings must not be worn thinner than about:", choices: ["1/8 inch", "1/4 inch", "1/2 inch", "1 inch"], a: 1, why: "Linings must not be loose, oil-soaked, or worn dangerously thin (less than 1/4 inch)." },
  { id: "ab-25", category: "airBrakes", topic: "Drums", q: "Brake drums or discs must not have cracks longer than:", choices: ["The full width of the drum", "One-half the width of the friction area", "1 inch regardless of size", "Cracks are always legal"], a: 1, why: "Cracks longer than half the friction-area width are a defect. Also look for overheating and loose parts." },
  { id: "ab-26", category: "airBrakes", topic: "Applied leak", q: "On the applied (1-minute hold) leakage test for a single vehicle, maximum air loss is:", choices: ["2 psi", "3 psi", "4 psi", "6 psi"], a: 1, why: "Applied leakage: 3 psi/minute single vehicle; 4 psi combination of 2; 6 psi combination of 3 or more." },
  { id: "ab-27", category: "airBrakes", topic: "Applied leak", q: "On the applied leakage test for a two-vehicle combination with air brakes on both units, maximum loss is:", choices: ["2 psi in 1 minute", "3 psi in 1 minute", "4 psi in 1 minute", "10 psi in 1 minute"], a: 2, why: "Combination of 2 vehicles: 4 psi in 1 minute with the service brake applied." },
  { id: "ab-28", category: "airBrakes", topic: "Static leak", q: "On the static leakage test (brakes released) for a single vehicle, maximum loss is:", choices: ["2 psi in 1 minute", "3 psi in 1 minute", "4 psi in 1 minute", "6 psi in 1 minute"], a: 0, why: "Static: 2 psi single; 3 psi combination of 2; 5 psi combination of 3+." },
  { id: "ab-29", category: "airBrakes", topic: "Build-up", q: "For dual air systems, pressure should build from about 85 to 100 psi within:", choices: ["10 seconds", "45 seconds", "3 minutes", "10 minutes"], a: 1, why: "At normal idle, dual systems should go from about 85 to 100 psi within 45 seconds." },
  { id: "ab-30", category: "airBrakes", topic: "Build-up", q: "On older single air systems, pressure should build from about 50 to 90 psi within:", choices: ["45 seconds", "90 seconds", "3 minutes", "10 minutes"], a: 2, why: "Pre-1975 single systems: 50–90 psi within 3 minutes. Skills-test in-cab checks also cite 50–90 within 3 minutes as a buildup standard on some vehicles." },
  { id: "ab-31", category: "airBrakes", topic: "Low air test", q: "To test the low-air warning, you fan off pressure. The warning must activate before pressure goes below:", choices: ["20 psi", "55 psi", "100 psi", "125 psi"], a: 1, why: "Verbalize that the device must work at no lower than 55 psi (typically 55–75 psi)." },
  { id: "ab-32", category: "airBrakes", topic: "S-cam", q: "The most common foundation brake on heavy vehicles is the:", choices: ["S-cam drum brake", "Electric trailer brake only", "Parking-brake hand lever", "Engine brake"], a: 0, why: "S-cam brakes are the most common. Air pushes a rod, slack adjuster twists the camshaft, S-cam spreads the shoes." },
  { id: "ab-33", category: "airBrakes", topic: "Front limiting valve", q: "If a vehicle has a front-brake limiting valve labeled Normal/Slippery, you should:", choices: ["Use Slippery in rain to cut front-brake air in half", "Keep it in Normal; front-wheel brakes are good under all conditions", "Remove it", "Use Slippery on dry pavement"], a: 1, why: "The Slippery position reduces stopping power. Tests show front-wheel brake skids are unlikely even on ice. Use Normal." },
  { id: "ab-34", category: "airBrakes", topic: "Fanning", q: "Repeatedly pumping the brake pedal when air pressure is already low can:", choices: ["Restore tank pressure", "Bleed away remaining air so you have even less braking", "Charge the compressor faster", "Release spring brakes"], a: 1, why: "Each apply uses air. Fanning a low system can use up what little air you have left." },
  { id: "ab-35", category: "airBrakes", topic: "Application gauge", q: "An application-pressure gauge shows:", choices: ["Tire pressure", "How much air pressure you are applying to the brakes", "Engine oil pressure", "Fuel level"], a: 1, why: "If you need more application pressure to hold the same downhill speed, brakes are fading." },
  { id: "ab-36", category: "airBrakes", topic: "Alcohol evaporator", q: "Some air systems have an alcohol evaporator to:", choices: ["Increase horsepower", "Introduce alcohol into the system to reduce the risk of ice in cold weather", "Clean the windshield", "Lubricate S-cams automatically"], a: 1, why: "Alcohol can help prevent ice in the air system. Tanks must still be drained; the evaporator is extra protection on some vehicles." },
  { id: "ab-37", category: "airBrakes", topic: "Service test", q: "During a moving service-brake test at about 5 mph, you are looking for:", choices: ["Pulling to one side, unusual feel, or delayed stopping", "Better radio reception", "Higher RPM", "ABS lamp flashing as a required pass"], a: 0, why: "A low-speed firm apply reveals pull, delay, or strange feel you might not notice until an emergency." },
  { id: "ab-38", category: "airBrakes", topic: "Parking test", q: "To test the parking brake:", choices: ["Set it and gently pull against it in a low gear", "Drive at 55 mph and yank the knob", "Drain all tanks first", "Push the pedal with springs applied"], a: 0, why: "Seat belt on, parking brake set, gentle pull in low gear to confirm it holds." },
  { id: "ab-39", category: "airBrakes", topic: "Stab braking", q: "Stab braking should only be used:", choices: ["On vehicles with working ABS on all axles", "On vehicles without ABS, by applying fully, releasing when wheels lock, then reapplying when they roll", "Instead of a parking brake", "To drain tanks"], a: 1, why: "Stab braking is a non-ABS emergency method. With ABS, keep firm pressure instead of pumping/stabbing." },
  { id: "ab-40", category: "airBrakes", topic: "Required ABS dates", q: "Truck tractors with air brakes built on or after which date are required to have ABS?", choices: ["March 1, 1997", "March 1, 2005", "January 1, 1980", "Only 2020 and newer"], a: 0, why: "Tractors: March 1, 1997. Other air-brake vehicles including trailers/dollies: March 1, 1998." },
  { id: "ab-41", category: "airBrakes", topic: "Wig-wag", q: "A wig-wag is:", choices: ["A type of fifth wheel", "A low-air warning arm that drops into the driver’s view", "A glad-hand seal", "An engine brake"], a: 1, why: "Some vehicles use a mechanical arm (wig-wag) as a visible low-air warning in the 55–75 psi range." },
  { id: "ab-42", category: "airBrakes", topic: "Auto slacks", q: "If automatic slack adjusters are out of adjustment, you should:", choices: ["Routinely crank them tighter every day as normal maintenance", "Take the vehicle for repair; manual adjustment usually only hides a mechanical problem", "Ignore them because they are automatic", "Remove them"], a: 1, why: "Manual adjustment of automatic slacks is a temporary emergency measure only. The underlying problem must be fixed." },
  { id: "ab-43", category: "airBrakes", topic: "Normal stop", q: "In a normal stop with a manual transmission, you should:", choices: ["Push the clutch in immediately as you start braking", "Control pedal pressure for a smooth stop and not depress the clutch until engine RPM is near idle", "Shift to reverse", "Use only the trailer hand valve"], a: 1, why: "Keep the engine connected for control and braking effect until RPM is down near idle, then clutch and select a starting gear." },
  { id: "ab-44", category: "airBrakes", topic: "Belt", q: "If the air compressor is belt-driven, during pre-trip you should check:", choices: ["Belt condition and tightness", "Only paint color", "Only the horn", "Only cargo seals"], a: 0, why: "A loose or damaged compressor belt can prevent the system from building air." },
  { id: "ab-45", category: "airBrakes", topic: "Hoses", q: "Air hoses to brake chambers must be:", choices: ["Cut and chafed so they flex more", "Free of cuts, rub wear, leaks, and poor connections", "Covered with grease", "Disconnected when driving"], a: 1, why: "Damaged hoses leak air and can cause brake failure. Inspect during the walk-around." },

  { id: "cv-01", category: "combination", topic: "Definition", q: "A combination vehicle is:", choices: ["Any truck with air conditioning", "A power unit coupled to one or more trailers", "A bus with standees", "A pickup under 10,000 pounds"], a: 1, why: "Combination means tractor-semitrailer or truck-trailer combinations." },
  { id: "cv-02", category: "combination", topic: "Fifth wheel", q: "The device that connects a tractor to a semitrailer is the:", choices: ["Fifth wheel", "Steering column", "Brake chamber", "Pintle hook only"], a: 0, why: "The fifth wheel on the tractor locks around the trailer kingpin." },
  { id: "cv-03", category: "combination", topic: "Kingpin", q: "The kingpin is:", choices: ["The steering-wheel lock", "The pin on the trailer that locks into the fifth-wheel jaws", "The trailer brake pedal", "The glad-hand seal"], a: 1, why: "Jaws must close on the shank of the kingpin, not the head." },
  { id: "cv-04", category: "combination", topic: "Grease", q: "Why should the fifth-wheel plate be greased as required?", choices: ["To reduce friction between tractor and trailer; lack of grease can cause steering problems", "To improve horn volume", "To raise air pressure", "To tighten lug nuts"], a: 0, why: "An unlubricated fifth wheel can bind and make steering difficult." },
  { id: "cv-05", category: "combination", topic: "Before coupling", q: "Before coupling, the fifth wheel should be:", choices: ["Tilted down toward the rear of the tractor, jaws open, unlocking handle in the automatic-lock position", "Tilted up toward the cab with jaws closed", "Removed", "Covered so you cannot see the jaws"], a: 0, why: "Correct attitude and open jaws let the kingpin enter and lock. Sliding fifth wheels must be locked." },
  { id: "cv-06", category: "combination", topic: "Alignment", q: "Why must the tractor be lined up straight with the trailer before coupling?", choices: ["Backing under at an angle can shove the trailer sideways and break the landing gear", "It increases engine RPM", "It drains air tanks", "It is only for looks"], a: 0, why: "Never back under at an angle. Crooked coupling damages landing gear and can miss the lock." },
  { id: "cv-07", category: "combination", topic: "Height", q: "Trailer height before coupling should be:", choices: ["Much higher than the fifth wheel so it drops on", "Slightly lower than the center of the fifth wheel so the trailer is raised slightly when you back under", "Exactly even with the cab roof", "Resting on the frame rails"], a: 1, why: "Slightly low trailer height lets the fifth wheel lift the trailer and complete a solid couple." },
  { id: "cv-08", category: "combination", topic: "Tug test", q: "After coupling, a tug test is used to:", choices: ["Warm the tires", "Confirm the fifth wheel is locked by gently pulling against the trailer brakes", "Drain the tanks", "Set cargo temperature"], a: 1, why: "With trailer brakes set, ease forward. If the couple is bad, you will pull out instead of towing the trailer." },
  { id: "cv-09", category: "combination", topic: "Visual lock", q: "After coupling you should look into the back of the fifth wheel to confirm:", choices: ["There is a large gap", "Locking jaws are closed around the shank of the kingpin and there is no space between upper and lower fifth wheel", "The kingpin is sitting on top of closed jaws", "The jaws are still open"], a: 1, why: "A gap can mean the kingpin is on top of closed jaws—the trailer can come off. Jaws must be on the shank." },
  { id: "cv-10", category: "combination", topic: "Landing gear", q: "Before driving, landing gear must be:", choices: ["Raised all the way up with the crank handle secured", "Left halfway down for stability", "Resting on the pavement", "Removed"], a: 0, why: "Part-way-up gear can snag tracks or pavement. Raise fully and stow the crank." },
  { id: "cv-11", category: "combination", topic: "Landing gear raise", q: "When raising landing gear after coupling:", choices: ["Use low gear until it is free of weight, then high gear, and raise completely", "Always stay in high gear under full trailer weight", "Leave it 6 inches down", "Raise only until it barely clears the ground"], a: 0, why: "Low gear starts the lift under load; high gear finishes after weight is off. Raise all the way." },
  { id: "cv-12", category: "combination", topic: "Air lines", q: "After coupling, which connections must be secured?", choices: ["Electrical cord and air lines (glad hands)", "Windshield wipers", "Fuel cap only", "Only the passenger mirror"], a: 0, why: "Glad hands and the 7-way (or equivalent) electrical connection must be locked, supported, and leak-free." },
  { id: "cv-13", category: "combination", topic: "Colors", q: "Emergency (supply) air lines are often color-coded ____; service lines ____.", choices: ["Blue; red", "Red; blue", "Yellow; green", "White; black"], a: 1, why: "Red = emergency/supply. Blue = service/control. Crossing them is dangerous." },
  { id: "cv-14", category: "combination", topic: "Crossed lines", q: "If you cross the air lines on a newer trailer with spring brakes:", choices: ["Nothing happens", "Supply air goes to the service line; trailer spring brakes may not release", "The tractor goes faster", "ABS turns off permanently"], a: 1, why: "Crossed lines can keep trailer parking springs applied. If springs do not release when you push the supply knob, check the connections." },
  { id: "cv-15", category: "combination", topic: "Old trailers", q: "If you cross air lines on an older trailer without spring brakes:", choices: ["You may be able to drive away with no trailer brakes—very dangerous", "The trailer cannot roll", "The tractor protection valve disappears", "The kingpin melts"], a: 0, why: "Without spring brakes, a crossed hookup can leave the trailer brakes inoperative while the wheels turn freely." },
  { id: "cv-16", category: "combination", topic: "Glad hands", q: "To couple glad hands you should:", choices: ["Press the seals together at about a 90-degree angle, then turn to lock", "Hammer them on", "Connect red to blue", "Leave one uncoupled for ABS"], a: 0, why: "Clean seals, 90-degree join, then twist to lock. Support hoses so they do not drag or snag." },
  { id: "cv-17", category: "combination", topic: "Supply knob", q: "The trailer air-supply control on newer vehicles is:", choices: ["A yellow diamond", "A red eight-sided knob: push in to supply the trailer, pull out to shut air off and set trailer emergency brakes", "The horn button", "The headlight switch"], a: 1, why: "Red octagon = tractor protection / trailer air supply. It should pop out around 20–45 psi if pressure is lost." },
  { id: "cv-18", category: "combination", topic: "Tractor protection", q: "The tractor protection valve:", choices: ["Keeps the tractor from losing all air if the trailer breaks away or a trailer air line fails", "Steers the trailer", "Greases the fifth wheel", "Charges the batteries"], a: 0, why: "It closes the air lines to the trailer to protect the tractor’s air supply." },
  { id: "cv-19", category: "combination", topic: "Off-tracking", q: "Trailer off-tracking means:", choices: ["The trailer wheels follow a shorter path than the tractor wheels in a turn", "The trailer passes the tractor", "The trailer has no lights", "The trailer is empty"], a: 0, why: "Rear wheels take a shorter path. You must turn wide enough so the trailer does not climb curbs or hit vehicles." },
  { id: "cv-20", category: "combination", topic: "Turns", q: "You should turn wide in a combination because of:", choices: ["Off-tracking", "Higher fuel use in a wide turn", "ABS rules", "Kingpin grease"], a: 0, why: "Off-tracking requires a wider path. Do not swing into other lanes any more than needed." },
  { id: "cv-21", category: "combination", topic: "Jackknife", q: "A jackknife is:", choices: ["The tractor and trailer folding toward each other", "A tire-inflation method", "A cargo strap", "A type of triangle"], a: 0, why: "Trailer-wheel lockup is a common cause of trailer jackknife. Drive-wheel lockup can cause a tractor jackknife." },
  { id: "cv-22", category: "combination", topic: "Jackknife", q: "Empty or lightly loaded trailers jackknife more easily because:", choices: ["They have less weight and traction on the trailer wheels, so those brakes can lock sooner", "They have stronger brakes than loaded trailers in every case", "They cannot turn", "They have no ABS lamps"], a: 0, why: "Light trailer axles lock more easily. Brake gently and never slam trailer-only brakes on slippery roads." },
  { id: "cv-23", category: "combination", topic: "Hand valve", q: "The trailer hand valve (trolley valve) should not be used for:", choices: ["Testing trailer brakes or preventing rollback in some starts", "Parking, because the air can leak away", "A tug test", "A gentle check of trailer brakes"], a: 1, why: "Do not use the hand valve to hold a parked vehicle. Air can leak and the vehicle can roll. Use parking brakes." },
  { id: "cv-24", category: "combination", topic: "Rollover", q: "The safest way to prevent a combination rollover is to:", choices: ["Slow down before curves and on-ramps/off-ramps", "Brake hard in every turn", "Shift in the curve", "Turn as sharply as possible"], a: 0, why: "More than half of tractor-trailer rollovers are linked to excessive speed in curves. High CG makes this worse." },
  { id: "cv-25", category: "combination", topic: "Center of gravity", q: "A high center of gravity will:", choices: ["Reduce rollover risk", "Increase rollover risk", "Eliminate off-tracking", "Shorten following distance legally"], a: 1, why: "Top-heavy loads roll more easily. Keep cargo low and slow down before turns." },
  { id: "cv-26", category: "combination", topic: "Uncouple", q: "When uncoupling, after pulling the tractor partly out you should stop with the tractor frame still under the trailer because:", choices: ["It looks professional", "If landing gear sinks or collapses, the tractor frame can still support the trailer", "It charges the ABS", "It greases the kingpin"], a: 1, why: "Never pull all the way out in one move. Pause with the frame under the trailer as a safety support." },
  { id: "cv-27", category: "combination", topic: "Uncouple pressure", q: "To ease pressure on fifth-wheel locking jaws before uncoupling:", choices: ["Back up gently, then set parking brakes while pushing against the kingpin", "Drive away at highway speed", "Raise the trailer off the fifth wheel with landing gear", "Disconnect the battery"], a: 0, why: "Backing gently takes load off the jaws so the release handle can be pulled." },
  { id: "cv-28", category: "combination", topic: "Loaded uncouple", q: "When lowering landing gear on a loaded trailer to uncouple:", choices: ["Lower to firm contact, then a few extra low-gear turns to take some weight off the tractor—do not lift the trailer off the fifth wheel", "Lift the trailer completely off the fifth wheel", "Leave the gear up", "Put the gear on a soft shoulder only"], a: 0, why: "A little extra cranking unloads the tractor slightly. Lifting off the fifth wheel is wrong and dangerous." },
  { id: "cv-29", category: "combination", topic: "Dummy couplers", q: "Glad hands should be put on dummy couplers or coupled together when not in use to:", choices: ["Keep water and dirt out of the lines", "Increase pressure", "Disable spring brakes", "Charge the electrical cord"], a: 0, why: "Dummy (dead-end) couplers protect seals and keep contamination out of the air system." },
  { id: "cv-30", category: "combination", topic: "Support lines", q: "Air and electrical lines must be supported so they:", choices: ["Cannot drag, snag, or be crushed in a turn", "Are stretched tight with zero slack", "Hang on the ground for cooling", "Are tied to a tire"], a: 0, why: "Enough slack for turns, but not so much they scrape or catch." },
  { id: "cv-31", category: "combination", topic: "Clearance", q: "After the trailer weight is on the tractor, check clearance so that in a sharp turn:", choices: ["The tractor frame will not hit landing gear and tires will not hit the trailer nose", "The radio antenna clears the load", "The fifth wheel is dry", "The supply knob is pulled out"], a: 0, why: "Landing-gear strike and cab/trailer contact are coupling-inspection items, especially with a sliding fifth wheel too far forward." },
  { id: "cv-32", category: "combination", topic: "Sliding fifth wheel", q: "A sliding fifth wheel must have:", choices: ["All locking pins in place and the slide locked; not so far forward that the frame hits landing gear in turns", "Pins removed for flexibility", "No grease", "Open jaws while driving"], a: 0, why: "Unlocked slides can move under the trailer. Position affects weight distribution and turn clearance." },
  { id: "cv-33", category: "combination", topic: "Test trailer brakes", q: "Always test trailer brakes before driving by:", choices: ["Using the hand valve or pulling the air-supply control, then pulling gently against them in low gear", "Honking twice", "Turning off the engine", "Releasing all air"], a: 0, why: "Confirm the trailer actually has brakes before you enter traffic." },
  { id: "cv-34", category: "combination", topic: "ABS mix", q: "If only the tractor has ABS:", choices: ["You should still brake normally; you can keep steering, but watch the trailer and ease off if it swings out", "You must pump the brakes", "Trailer brakes will not work", "You can drive faster in curves"], a: 0, why: "Partial ABS still helps. Brake normally. If the trailer swings, ease off if it is safe." },
  { id: "cv-35", category: "combination", topic: "Crack the whip", q: "Rearward amplification (“crack-the-whip”) is more severe when:", choices: ["You make a sudden lane change or swerve with a combination, especially doubles", "You drive slowly in a straight line", "The fifth wheel is greased", "ABS is working"], a: 0, why: "The rear unit can swing much farther than the tractor. Avoid abrupt steering inputs." },
  { id: "cv-36", category: "combination", topic: "Following", q: "Combinations need more following distance than many straight trucks because:", choices: ["They are shorter", "They often need more stopping distance and have more severe crash results if you hit someone", "They have no brakes", "Off-tracking shortens stops"], a: 1, why: "Weight, air-brake lag, and multiple units mean more space. Hitting a car from behind is a common, serious CMV crash." },
  { id: "cv-37", category: "combination", topic: "Chock", q: "Before coupling or uncoupling, wheels should be chocked if:", choices: ["You have any doubt the brakes will hold the trailer", "The trailer is on a perfectly level shop floor with spring brakes confirmed and you never chock as a habit", "It is raining", "ABS is on"], a: 0, why: "Chock whenever you are not sure the trailer cannot roll—especially older trailers without spring brakes." },
  { id: "cv-38", category: "combination", topic: "Electric", q: "The trailer electrical cord should be:", choices: ["Firmly seated, locked, and supported with slack for turns", "Dangling on the catwalk", "Spliced with tape as a normal method", "Disconnected while driving to save bulbs"], a: 0, why: "A loose 7-way causes dark trailers and ABS communication problems. Inspect it every couple." },
  { id: "cv-39", category: "combination", topic: "Kingpin inspect", q: "Before coupling, inspect the kingpin for:", choices: ["Bends, cracks, or damage", "Paint color only", "Grease on the cab", "Tire brand"], a: 0, why: "A bent or broken kingpin can prevent a safe lock." },
  { id: "cv-40", category: "combination", topic: "Safety latch", q: "After coupling, the fifth-wheel safety latch / lock should be:", choices: ["In position over the locking lever (some must be set by hand)", "Left off so uncoupling is faster", "Wired open", "Greased shut so it cannot move"], a: 0, why: "The safety latch keeps the release handle from opening on the road." },

  { id: "dt-01", category: "doubles", topic: "Weight order", q: "For the safest handling of doubles, the more heavily loaded trailer should be:", choices: ["In the rear", "In the first position behind the tractor", "On the dolly only", "Empty"], a: 1, why: "Heavier first, lighter in the rear reduces instability and rearward amplification." },
  { id: "dt-02", category: "doubles", topic: "Dolly", q: "A converter dolly is:", choices: ["A coupling device with a fifth wheel used to hitch a second semitrailer", "A type of engine brake", "A cargo heater", "A slack adjuster"], a: 0, why: "The dolly’s fifth wheel couples the rear semitrailer; a pintle hitch connects the dolly to the lead trailer." },
  { id: "dt-03", category: "doubles", topic: "Spring brakes", q: "Converter dollies:", choices: ["Always have spring brakes", "Are not required to have spring brakes, and many do not", "Never have wheels", "Replace the tractor protection valve"], a: 1, why: "Know how to set emergency brakes or chock a dolly/second trailer that may not have parking springs." },
  { id: "dt-04", category: "doubles", topic: "Secure second", q: "If the second trailer has no spring brakes, one way to set its emergency brakes before coupling is to:", choices: ["Connect the emergency line, charge the tank, then disconnect the emergency line", "Fill the tires with water", "Remove the glad hands permanently", "Open the rear shut-off valves"], a: 0, why: "Charging then disconnecting the emergency (supply) line sets emergency brakes on trailers that work that way. Chock if unsure." },
  { id: "dt-05", category: "doubles", topic: "Shut-offs", q: "Shut-off valves should be:", choices: ["Closed on the rear of the last trailer and open on the others", "Open on every trailer including the last", "Closed on the first trailer only", "Removed"], a: 0, why: "Last trailer rear valves closed so air does not escape. Intermediate valves open so air reaches every trailer." },
  { id: "dt-06", category: "doubles", topic: "Pintle", q: "When coupling a dolly to the lead trailer, the pintle hook must be:", choices: ["Locked, with the dolly support raised and secured when required", "Left open for flexibility", "Wired to a brake chamber", "Greased instead of locked"], a: 0, why: "An unlocked pintle can drop the dolly. Inspect the hook, safety latch, and eye." },
  { id: "dt-07", category: "doubles", topic: "Whip", q: "Doubles and triples are more likely to turn over than a single trailer partly because of:", choices: ["Rearward amplification (crack-the-whip)", "Having too many mirrors", "Lower center of gravity", "Shorter stopping distance always"], a: 0, why: "A quick steer at the tractor can become a much larger swing at the rear trailer." },
  { id: "dt-08", category: "doubles", topic: "California", q: "Triple trailer combinations on public highways in California are:", choices: ["Generally not legal", "Required for Class A", "Allowed on every city street", "The same as a single 53-foot trailer"], a: 0, why: "California does not allow triple trailers. The T endorsement still matters if you will operate doubles here or triples in states that allow them." },
  { id: "dt-09", category: "doubles", topic: "Pull dolly", q: "Why pull a dolly out from under a trailer before disconnecting it from the trailer in front?", choices: ["The trailer could fall or the dolly could jackknife/upend if still coupled when the lead unit pulls away", "It saves grease", "It is required for ABS", "It charges the second trailer"], a: 0, why: "Unhook in the correct order so the rear trailer and dolly stay controlled and supported." },
  { id: "dt-10", category: "doubles", topic: "Air flow", q: "You can test that air flows to all trailers by:", choices: ["Opening the rear emergency line shut-off on the last trailer and listening/feeling for air, then closing it", "Honking", "Watching only the fuel gauge", "Disconnecting the electrical cord"], a: 0, why: "After charging, check that air reaches the last trailer, then close the last valves." },
  { id: "dt-11", category: "doubles", topic: "Dolly height", q: "Before coupling a dolly to a second semitrailer, trailer height should be:", choices: ["Slightly lower than the dolly fifth wheel so the trailer rises as you push under", "Much higher so it drops", "Irrelevant", "Level with the tractor roof"], a: 0, why: "Same principle as tractor coupling: slight lift as the fifth wheel goes under." },
  { id: "dt-12", category: "doubles", topic: "Steering", q: "To reduce crack-the-whip risk with doubles you should:", choices: ["Steer smoothly and avoid sudden lane changes", "Swerve early and often", "Brake only with the last trailer hand valve", "Travel empty in the front trailer always"], a: 0, why: "Smooth inputs keep the rear trailer from amplifying the motion." },
  { id: "dt-13", category: "doubles", topic: "Backing", q: "Backing doubles is:", choices: ["Generally avoided; it is harder than backing a single and often requires spotting and extra room", "Easier than backing a straight truck", "Illegal in all states", "Done at highway speed"], a: 0, why: "Two pivot points make backing doubles difficult. Avoid it; get help if you must." },
  { id: "dt-14", category: "doubles", topic: "Inspect dolly", q: "When inspecting a converter dolly, check:", choices: ["Fifth wheel, pintle eye/hook, air and electrical lines, wheels/tires, and brakes", "Only the paint", "Only the license plate", "Only cargo seals"], a: 0, why: "The dolly is a full coupling and brake unit. Inspect it like a small trailer." },
  { id: "dt-15", category: "doubles", topic: "Jackknife", q: "Doubles are more likely to jackknife than a single trailer because:", choices: ["There are more articulation points and the rear unit is lighter/more mobile", "They have no brakes", "Off-tracking disappears", "They cannot use ABS"], a: 0, why: "More hinges and often a light rear trailer increase jackknife and whip risk." },

  { id: "tk-01", category: "tanker", topic: "Surge", q: "Liquid surge is:", choices: ["The forward/backward/sideways movement of liquid in a tank that can push the vehicle", "A type of ABS", "A coupling method", "Tire hydroplaning only"], a: 0, why: "When you brake, liquid rushes forward and can shove the tractor; when you stop, it can hit again. Smooth driving is required." },
  { id: "tk-02", category: "tanker", topic: "Baffles", q: "Baffled tanks:", choices: ["Completely eliminate surge", "Have bulkheads with holes that slow surge but do not stop it", "Are illegal in California", "Are only for dry bulk"], a: 1, why: "Baffles reduce surge, especially front-to-back, but you still must manage liquid movement." },
  { id: "tk-03", category: "tanker", topic: "Smoothbore", q: "Unbaffled (smooth bore) tanks:", choices: ["Have less surge than baffled tanks", "Are common for food-grade liquids and have more surge, so they need even smoother driving", "Cannot roll over", "Do not need outage"], a: 1, why: "Sanitary tanks are often smooth inside. Surge is worse. Drive as if the load is trying to keep moving." },
  { id: "tk-04", category: "tanker", topic: "Outage", q: "Outage is:", choices: ["Empty space left in a tank for liquid expansion", "A type of glad hand", "Brake lag", "Off-tracking"], a: 0, why: "Liquids expand with heat. Never fill a cargo tank completely full; leave required outage." },
  { id: "tk-05", category: "tanker", topic: "Curves", q: "Tank vehicles have a high center of gravity, so you should:", choices: ["Take curves and ramps extra slowly", "Brake hard in every curve", "Drive faster when half full", "Rely on baffles instead of speed control"], a: 0, why: "Tanks are top-heavy. Half-full tanks can also have more surge. Slow before the curve." },
  { id: "tk-06", category: "tanker", topic: "Braking", q: "To control surge when stopping a tanker:", choices: ["Brake smoothly and steadily; do not lock the wheels", "Stab the brakes repeatedly as a first choice with ABS", "Use only the trailer hand valve at highway speed", "Downshift into reverse"], a: 0, why: "A smooth stop lets the liquid settle. Locked wheels plus surge can jackknife or pull you out of your lane." },
  { id: "tk-07", category: "tanker", topic: "Bulkheads", q: "Bulkheads in a tank:", choices: ["Divide the tank into compartments, which can reduce surge but each compartment still surges", "Remove the need for a CDL", "Are the same as tires", "Eliminate outage rules"], a: 0, why: "Compartmented tanks still need careful driving; unequal compartment loading also affects handling." },
  { id: "tk-08", category: "tanker", topic: "Definition", q: "A tank vehicle endorsement is generally required for tanks with:", choices: ["An individual capacity over 119 gallons and aggregate capacity of 1,000 gallons or more, permanently or temporarily attached", "Any water bottle", "Only side-saddle diesel tanks on a tractor", "Only portable 5-gallon cans"], a: 0, why: "The N endorsement covers large cargo tanks/portable tanks meeting those capacity rules (empty storage containers designed for transport also have rules)." },
  { id: "tk-09", category: "tanker", topic: "Skid", q: "If you feel a tanker start to skid from surge, you should:", choices: ["Steer and counter-steer smoothly and get off the brakes if wheels lock (unless using ABS as trained)", "Accelerate hard", "Apply parking brakes", "Turn more sharply"], a: 0, why: "Regain roll and steering first. Sudden extra braking can make surge worse." },
  { id: "tk-10", category: "tanker", topic: "Inspect", q: "Before loading or driving a cargo tank, inspect:", choices: ["Manholes, valves, pipes, and gaskets for leaks and that covers are secure", "Only the radio", "Only the fifth-wheel grease", "Only the horn"], a: 0, why: "Leaking valves or loose manhole covers can spill product. Check after loading as well." },
  { id: "tk-11", category: "tanker", topic: "Curves empty", q: "An empty tank vehicle still needs caution in curves because:", choices: ["The high tank body still has a relatively high center of gravity compared with many dry vans", "Empty tanks cannot roll", "ABS does not work empty", "Outage becomes negative"], a: 0, why: "The tank structure sits high even when empty. Do not treat empty as automatically stable." },
  { id: "tk-12", category: "tanker", topic: "Start/stop", q: "When starting a loaded tanker on a grade:", choices: ["Release brakes smoothly and apply power without jerking, which can start surge", "Dump the clutch", "Use only trailer brakes at 30 mph", "Coast backward first"], a: 0, why: "Rough starts and stops move the liquid. Smooth power and braking are tank-driving basics." },
  { id: "tk-13", category: "tanker", topic: "Side surge", q: "Side-to-side surge is especially dangerous because it can:", choices: ["Cause a rollover", "Fill the air tanks", "Lock the fifth wheel", "Cool the brakes"], a: 0, why: "Liquid hitting one side in a curve or lane change raises rollover risk. Baffles help less with side surge than some drivers think." },
  { id: "tk-14", category: "tanker", topic: "Portable", q: "Portable tanks on a truck:", choices: ["Must be properly secured; they can still surge and have high CG", "Never need an endorsement", "Can be left unlatched", "Are exempt from leaks"], a: 0, why: "Portable tanks that meet capacity rules still need the N endorsement and must be secured against movement." },
  { id: "tk-15", category: "tanker", topic: "Never fill", q: "You should never load a tank completely full because:", choices: ["Liquid expands with temperature; without outage the tank can overflow or be over-pressured", "It reduces surge to zero", "DOT forbids all partial loads", "ABS will not work"], a: 0, why: "Leave required outage. Expansion space is a legal and safety requirement." },

  { id: "hz-01", category: "hazmat", topic: "Placards", q: "A placarded vehicle must have at least how many identical placards?", choices: ["2", "3", "4", "8"], a: 2, why: "Front, rear, and both sides—readable from all four directions." },
  { id: "hz-02", category: "hazmat", topic: "Shape", q: "HazMat placards are:", choices: ["Square-on-point diamonds at least 9.84 inches (250 mm)", "Round 3-inch stickers", "Only on shipping papers", "Optional if you drive slowly"], a: 0, why: "Diamond-shaped, 250 mm, upright on a point." },
  { id: "hz-03", category: "hazmat", topic: "Endorsement", q: "To drive a vehicle that requires HazMat placards you need:", choices: ["No extra test", "A CDL with an H endorsement and a TSA security threat assessment", "Only a Class C car license", "Only air-brake knowledge"], a: 1, why: "H endorsement knowledge test plus TSA background check. X is H plus tank." },
  { id: "hz-04", category: "hazmat", topic: "Papers", q: "HazMat shipping papers must be:", choices: ["On top of other papers and kept in the required in-cab location so they can be found quickly after a crash", "In a locked trailer only", "Mailed to DOT before each trip", "Optional if placarded"], a: 0, why: "Emergency responders need the papers. Keep them in the driver’s door pouch, on the seat, or as the rules specify—not buried." },
  { id: "hz-05", category: "hazmat", topic: "ERG", q: "The Emergency Response Guidebook (ERG) is used to:", choices: ["Identify hazards and initial isolation/response for a material using the ID number or name", "Calculate fuel tax", "Adjust slack adjusters", "Couple glad hands"], a: 0, why: "UN/NA ID numbers on papers and orange panels/placards tie to ERG guides." },
  { id: "hz-06", category: "hazmat", topic: "Classes", q: "How many DOT hazardous material classes are there?", choices: ["3", "6", "9", "12"], a: 2, why: "Classes 1–9: explosives, gases, flammable liquids, flammable solids, oxidizers/organic peroxides, toxics, radioactive, corrosives, miscellaneous." },
  { id: "hz-07", category: "hazmat", topic: "Smoke", q: "You should not smoke within 25 feet of a vehicle when it contains:", choices: ["Class 1 explosives, Class 3 flammable liquids, or flammable gas, among other listed materials", "Only bottled water", "Only sealed empty boxes with no residue", "Only furniture"], a: 0, why: "No smoking around many hazard classes. Know the 25-foot rule from Section 9." },
  { id: "hz-08", category: "hazmat", topic: "Load", q: "When loading HazMat you must:", choices: ["Follow segregation rules so incompatible materials are not loaded together", "Mix all classes to save space", "Always load explosives with oxidizers", "Leave packages unsecured for ventilation"], a: 0, why: "Segregation tables forbid certain combinations. Secure packages against movement." },
  { id: "hz-09", category: "hazmat", topic: "Tires", q: "On a placarded vehicle, if you have a dual tire that is overheated you should:", choices: ["Stay with the vehicle until the tire cools; an overheated tire can cause a fire or explosion with some loads", "Drive faster to cool it", "Park in a tunnel", "Ignore it if the other dual is fine"], a: 0, why: "Stop and cool overheated tires. Do not continue with a dangerous tire on a HazMat load." },
  { id: "hz-10", category: "hazmat", topic: "Tunnel", q: "Some HazMat is restricted from:", choices: ["Tunnels, certain bridges, and routes listed in regulations or on the shipping paper", "All parking lots", "All two-lane roads", "All weigh stations"], a: 0, why: "Route restrictions exist. Follow the shipper’s instructions and federal/state rules." },
  { id: "hz-11", category: "hazmat", topic: "Leaks", q: "If you discover a leak or spill of HazMat:", choices: ["Follow emergency procedures, keep people away, and use the shipping papers/ERG; do not transfer product unless trained and it is safe", "Hide the leak and finish the delivery", "Taste the product to identify it", "Wash it into a storm drain"], a: 0, why: "Protect life first. Warn others, notify emergency services, and do not take actions you are not trained for." },
  { id: "hz-12", category: "hazmat", topic: "Who", q: "Who certifies that a HazMat shipment is properly offered (packaged, marked, labeled, documented)?", choices: ["The shipper", "Any passing motorist", "Only the fuel-desk clerk", "The trailer manufacturer"], a: 0, why: "The shipper certifies. The carrier/driver must not accept an improper shipment and must check papers, placards, and loading." },
  { id: "hz-13", category: "hazmat", topic: "Accept", q: "A driver should not accept a HazMat load if:", choices: ["Packages are damaged, leaking, or papers/placards are missing or wrong", "The shipper certified it, regardless of obvious leaks", "It is raining", "The tank has proper outage"], a: 0, why: "Do not accept leaking or improperly prepared HazMat. You share responsibility once you take the load." },
  { id: "hz-14", category: "hazmat", topic: "ID number", q: "A 4-digit UN/NA ID number:", choices: ["Identifies the material for emergency responders and may appear on placards or orange panels", "Is the driver’s CDL number", "Is the tractor VIN", "Replaces shipping papers"], a: 0, why: "ID numbers are on shipping papers and often on the vehicle. Use them with the ERG." },
  { id: "hz-15", category: "hazmat", topic: "Empty", q: "Empty tanks or packages that still contain HazMat residue:", choices: ["May still be regulated and may still need placards until cleaned/purged as required", "Are never HazMat", "Can be marked as general freight always", "Do not need securement"], a: 0, why: "Residue can still be hazardous. Empty does not automatically mean unregulated." },

  { id: "ps-01", category: "passenger", topic: "Rails", q: "Buses must stop at railroad crossings:", choices: ["Within 15 to 50 feet of the nearest rail, look and listen, then cross without shifting", "Only if a train is visible", "On the tracks if traffic is ahead", "At 55 mph if the lights are not flashing"], a: 0, why: "Stop 15–50 feet from the nearest rail (with listed exceptions), then cross in a gear that will not require shifting." },
  { id: "ps-02", category: "passenger", topic: "Drawbridge", q: "At a drawbridge without a signal or attendant, a bus must:", choices: ["Stop at least 50 feet before the draw and not proceed until it is completely closed", "Never stop", "Speed up", "Honk and continue"], a: 0, why: "Uncontrolled drawbridges require a stop at least 50 feet before the draw." },
  { id: "ps-03", category: "passenger", topic: "Standee", q: "No passenger may stand:", choices: ["Forward of the standee line or in a way that blocks the driver’s vision", "In the aisle ever, on any bus", "Only if holding a ticket", "Behind the rear axle"], a: 0, why: "Keep the driver’s view and controls clear. Follow standee-line and aisle rules." },
  { id: "ps-04", category: "passenger", topic: "Exits", q: "Emergency exits must be:", choices: ["Operational, labeled, and never blocked by passengers or freight", "Tied shut for highway speeds", "Used as storage", "Locked from the outside only"], a: 0, why: "Blocked or inoperative emergency exits are a serious violation and a test item." },
  { id: "ps-05", category: "passenger", topic: "Fuel", q: "You should not refuel a bus:", choices: ["In a closed building with riders aboard, or with the engine running (follow handbook rules)", "At any truck stop ever", "With the parking brake set", "During daylight"], a: 0, why: "Fueling with passengers aboard in an enclosed building is prohibited. Avoid fueling with riders on board except as specifically allowed." },
  { id: "ps-06", category: "passenger", topic: "Count", q: "When arriving at destination or intermediate stops, a professional bus driver should:", choices: ["Make sure passengers are accounted for and nothing is left that creates a hazard", "Leave immediately without looking", "Lock riders in", "Turn off all lights including markers while unloading on the road"], a: 0, why: "Prevent leaving people or hazardous items. Supervise unloading." },
  { id: "ps-07", category: "passenger", topic: "Railroad exception", q: "A bus is not required to stop at a railroad crossing if:", choices: ["The crossing is marked exempt or is controlled in a way the handbook lists as an exception, such as a traffic light or an attendant directing traffic", "The bus is late", "Passengers vote to continue", "It is a school bus"], a: 0, why: "Know the listed exceptions (exempt signs, traffic-light-controlled, etc.). School buses have their own stricter rules." },
  { id: "ps-08", category: "passenger", topic: "Smooth", q: "Passenger comfort and safety require:", choices: ["Smooth starts, stops, and turns so people are not thrown", "Maximum acceleration from every stop", "Hard braking to train riders to hold on", "Open emergency doors on the highway"], a: 0, why: "Riders are unrestrained compared with cargo. Drive more smoothly than you would with freight." },
  { id: "ps-09", category: "passenger", topic: "Evacuation", q: "If you must evacuate a bus:", choices: ["Stop in a safe place, explain, and use the safest exits; keep people in a group away from traffic and the bus if there is fire or hazard", "Leave riders on the bus in a fire", "Evacuate into traffic lanes", "Hide the shipping papers"], a: 0, why: "Lead the evacuation. Fire, security, and position on the road determine which exits to use." },
  { id: "ps-10", category: "passenger", topic: "Prohibited", q: "Which is a common prohibited practice on a bus?", choices: ["Allowing riders to occupy the stepwell when the bus is moving", "Using mirrors", "Announcing stops", "Wearing a seat belt"], a: 0, why: "Doors and stepwells must be clear. Riders in the stepwell can fall out." },
  { id: "ps-11", category: "passenger", topic: "Inspection", q: "A passenger-vehicle pre-trip includes extra attention to:", choices: ["Seating, emergency exits, signaling devices, and passenger-area hazards", "Only the fifth wheel", "Only kingpin grease", "Only tanker baffles"], a: 0, why: "Section 4 adds passenger-compartment and emergency-equipment items to the basic inspection." },
  { id: "ps-12", category: "passenger", topic: "Bridge", q: "If a bus stalls on railroad tracks you should:", choices: ["Evacuate immediately and get people away from the tracks, then contact the railroad if possible", "Stay on board and wait", "Try to push the bus with riders still in the aisle", "Lie down on the tracks to signal"], a: 0, why: "Get people off and away. A train cannot stop in time." },

  { id: "pt-01", category: "pretrip", topic: "Approach", q: "When approaching the vehicle to inspect, you should look for:", choices: ["Leaks under the vehicle, lean/damage, and hazards around it (people, objects, low wires)", "Only whether it is your favorite color", "Only the fuel brand", "Only interior radio presets"], a: 0, why: "Step 1 of the 7-step method starts before you touch the cab." },
  { id: "pt-02", category: "pretrip", topic: "Engine", q: "Engine-compartment checks include:", choices: ["Leaks, oil/coolant/power-steering/fuel levels, belts, hoses, and loose parts", "Only the horn", "Only windshield tint", "Only cargo seals"], a: 0, why: "Fluids, belts, hoses, and leaks are core engine-compartment items." },
  { id: "pt-03", category: "pretrip", topic: "Oil", q: "When checking engine oil you should confirm:", choices: ["Proper level and no visible leak", "That the dipstick is missing", "Tire tread", "Trailer height"], a: 0, why: "Low oil or a leak is a no-go until corrected." },
  { id: "pt-04", category: "pretrip", topic: "Steering", q: "Steering components should be:", choices: ["Securely mounted, not damaged or missing, without excessive play", "Paint-matched only", "Loose for easier turning", "Disconnected"], a: 0, why: "Name parts (steering box, linkage, hoses, pump) and explain what would be a defect." },
  { id: "pt-05", category: "pretrip", topic: "Suspension", q: "Leaf springs and suspension should be checked for:", choices: ["Cracks, missing leaves, shift, leaking air bags, and secure U-bolts/mounts", "Fuel level", "Radio reception", "Clean windows only"], a: 0, why: "Broken springs, leaking air suspension, and loose mounts are out-of-service items." },
  { id: "pt-06", category: "pretrip", topic: "Tires", q: "Tire inspection includes:", choices: ["Inflation, tread depth, sidewalls, dual spacing, and damage (cuts, bulges, fabric showing)", "Brand name only", "Color only", "Valve-cap style only"], a: 0, why: "Steering tires 4/32\", others 2/32\", no recaps on steering axle of some vehicles, matching duals." },
  { id: "pt-07", category: "pretrip", topic: "Wheels", q: "Wheels and rims should be inspected for:", choices: ["Cracks, unseated locking rings, missing/loose lugs, and leaking hub seals", "Windshield wipers", "Trailer doors only", "Engine belts"], a: 0, why: "A cracked rim or missing lug can lose a wheel. Hub oil/grease leaks matter too." },
  { id: "pt-08", category: "pretrip", topic: "Chambers", q: "Brake chambers should be:", choices: ["Securely mounted, not cracked, not leaking air", "Used as steps", "Covered in oil", "Disconnected for the road test"], a: 0, why: "Damaged chambers or leaking caging bolts are defects. Mention pushrod stroke if asked." },
  { id: "pt-09", category: "pretrip", topic: "Lights", q: "Lighting inspection must verify:", choices: ["Headlights, clearance, markers, turns, brakes, 4-ways, and reflectors are clean and working", "Only headlights", "Only interior lights", "Only one marker"], a: 0, why: "Walk the vehicle. Have a helper or use reflections to see brake lights." },
  { id: "pt-10", category: "pretrip", topic: "Cab safety", q: "In-cab safety equipment that should be present includes:", choices: ["Fire extinguisher, warning devices, and spare fuses if required", "Only bottled water", "Only a flashlight", "Only tools"], a: 0, why: "Point to the extinguisher (charged, rated, mounted) and triangles." },
  { id: "pt-11", category: "pretrip", topic: "Belt", q: "The driver’s seat belt must be:", choices: ["Securely mounted, not cut or frayed, and latched properly", "Tucked behind the seat", "Used only on freeways", "Decorative"], a: 0, why: "You will be required to wear it. Inspect it during in-cab checks." },
  { id: "pt-12", category: "pretrip", topic: "Mirrors", q: "Mirrors must be:", choices: ["Secure, clean, and adjusted before moving", "Folded in for aerodynamics while driving in the city", "Removed", "Loose so they vibrate"], a: 0, why: "Adjust before the skills test so you can see down both sides and to the rear." },
  { id: "pt-13", category: "pretrip", topic: "Windshield", q: "The windshield should be:", choices: ["Clean, without damage in the driver’s view, with working wipers and washers", "Covered with stickers in the view area", "Tinted as dark as possible in front", "Cracked as long as you can see around it"], a: 0, why: "Illegal stickers and cracks in the critical view area fail the inspection." },
  { id: "pt-14", category: "pretrip", topic: "Air tests", q: "Required in-cab air-brake tests on the skills test typically include:", choices: ["Applied leakage, low-air warning, and spring-brake/tractor-protection pop-out (plus buildup as required)", "Only honking", "Only a tug test", "Only checking the radio"], a: 0, why: "You must demonstrate and verbalize the parameters. Missing a required air test is an automatic inspection failure." },
  { id: "pt-15", category: "pretrip", topic: "Verbalize", q: "During the CDL inspection test you must:", choices: ["Point to or touch each item, name it, and explain what you are looking for and why it matters", "Walk silently around the truck", "Only inspect the left side", "Skip coupling if it looks okay"], a: 0, why: "Examiners score what you show and say. Silent glances do not count." },
  { id: "pt-16", category: "pretrip", topic: "Coupling inspect", q: "Combination inspection of the fifth wheel includes:", choices: ["Mount, grease, no gap, jaws on kingpin shank, release arm seated, safety latch engaged", "Only that the trailer is a dry van", "Only tire brand", "Only the fuel cap"], a: 0, why: "Section 6.5 and the skills test score sheet both emphasize a complete couple check." },
  { id: "pt-17", category: "pretrip", topic: "Landing gear inspect", q: "Landing gear should be:", choices: ["Fully raised, no missing parts, crank secured, support frame not damaged", "Down on the highway", "Loose enough to rattle", "Bent is acceptable"], a: 0, why: "Damaged or down gear can catch on the road or fail at a shipper." },
  { id: "pt-18", category: "pretrip", topic: "Doors", q: "Trailer doors, ties, and cargo area should be checked so that:", choices: ["Doors are closed/locked or cargo is contained, and nothing will spill or fall", "Doors can swing freely on the highway", "Seal is broken if you are curious", "Only the left door matters"], a: 0, why: "Unsecured doors and leaking/falling cargo are inspection and en-route items." },
  { id: "pt-19", category: "pretrip", topic: "Exhaust inspect", q: "Exhaust should be:", choices: ["Secure, not leaking, and not touching wires, fuel, or air lines", "Patched with tape as a normal repair", "Routed through the cab for heat", "Disconnected to save backpressure"], a: 0, why: "Leaks poison the cab; contact with fuel or air lines is a fire/brake hazard." },
  { id: "pt-20", category: "pretrip", topic: "Attempts", q: "For the California CDL skills test, you are allowed up to how many attempts for inspection, basic control, and road test components?", choices: ["One total", "Three attempts (retest fees apply; failing one part postpones the rest that day as described by DMV)", "Unlimited the same day", "Ten"], a: 1, why: "DMV: three tries to pass the skills test. Fail a portion and remaining testing is postponed. Retest fees apply." }
];
